// =============================================
// Bot Health Monitor — All Health Checks
// =============================================
const cfg = $getWorkflowStaticData('global');

const isTestnet = (cfg.BYBIT_TESTNET || 'true').toLowerCase() === 'true';
const baseUrl = isTestnet ? 'https://api-testnet.bybit.com' : 'https://api.bybit.com';
const apiKey = cfg.BYBIT_API_KEY;
const apiSecret = cfg.BYBIT_API_SECRET;
const MAX_OPEN_POSITIONS = parseInt(cfg.MAX_OPEN_POSITIONS || '5');

// Helper: Moscow time
function moscowNow() {
  return new Date(Date.now() + 3 * 60 * 60 * 1000);
}

// Signed GET request helper
async function signedGet(endpoint, params) {
  const timestamp = Date.now().toString();
  const recvWindow = '5000';
  const qs = Object.entries(params).map(([k,v]) => `${k}=${v}`).join('&');
  const preSign = timestamp + apiKey + recvWindow + qs;
  const signature = hmacSHA256(apiSecret, preSign);
  return this.helpers.httpRequest({
    method: 'GET',
    url: `${baseUrl}${endpoint}?${qs}`,
    headers: {
      'X-BAPI-API-KEY': apiKey,
      'X-BAPI-SIGN': signature,
      'X-BAPI-TIMESTAMP': timestamp,
      'X-BAPI-RECV-WINDOW': recvWindow,
      'Content-Type': 'application/json'
    }
  });
}

const alerts = [];
const now = Date.now();

// Initialize health data in static data
if (!cfg.health_errors) cfg.health_errors = {};
if (!cfg.health_alerts_sent) cfg.health_alerts_sent = {};
if (!cfg.health_history) cfg.health_history = [];
if (!cfg.health_api_down_since) cfg.health_api_down_since = null;
if (!cfg.health_issues_active) cfg.health_issues_active = {};

// Startup detection
if (!cfg.health_started) {
  cfg.health_started = true;
  alerts.push({
    level: 'INFO',
    key: 'startup',
    message: '\ud83d\udd04 Bot Medic \u043f\u0435\u0440\u0435\u0437\u0430\u043f\u0443\u0441\u0442\u0438\u043b\u0441\u044f, \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u044e \u0441\u0438\u0441\u0442\u0435\u043c\u044b...'
  });
}

// =============================================
// a) API Health Check
// =============================================
let apiOk = false;
let apiResponseTime = 0;
try {
  const startTime = Date.now();
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: `${baseUrl}/v5/market/time`
  });
  apiResponseTime = Date.now() - startTime;

  if (resp.retCode === 0) {
    apiOk = true;
    // Recovery check
    if (cfg.health_api_down_since) {
      const downDuration = now - cfg.health_api_down_since;
      alerts.push({
        level: 'RECOVERY',
        key: 'api_down',
        description: 'Bybit API \u0431\u044b\u043b\u043e \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e',
        duration: Math.round(downDuration / 1000) + ' \u0441\u0435\u043a'
      });
      cfg.health_api_down_since = null;
      // Restore bot if it was stopped by medic
      if (cfg.botStopped && cfg.botStoppedByMedic) {
        cfg.botStopped = false;
        cfg.botStoppedByMedic = false;
      }
    }
    if (apiResponseTime > 5000) {
      alerts.push({
        level: 'WARNING',
        key: 'api_slow',
        description: `Bybit API \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442 \u043c\u0435\u0434\u043b\u0435\u043d\u043d\u043e: ${apiResponseTime}ms`,
        cause: '\u0412\u044b\u0441\u043e\u043a\u0430\u044f \u043d\u0430\u0433\u0440\u0443\u0437\u043a\u0430 \u043d\u0430 API \u0438\u043b\u0438 \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u044b \u0441 \u0441\u0435\u0442\u044c\u044e',
        recommendation: '\u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u0441\u0442\u0430\u0442\u0443\u0441 Bybit \u043d\u0430 status.bybit.com'
      });
    }
  } else {
    throw new Error(`retCode=${resp.retCode}: ${resp.retMsg}`);
  }
} catch(e) {
  apiOk = false;
  if (!cfg.health_api_down_since) {
    cfg.health_api_down_since = now;
  }
  const downDuration = now - cfg.health_api_down_since;

  if (downDuration > 2 * 60 * 1000) {
    // API down > 2 minutes — stop bot
    cfg.botStopped = true;
    cfg.botStoppedByMedic = true;
    cfg.stoppedAt = new Date().toISOString();
    alerts.push({
      level: 'CRITICAL',
      key: 'api_down',
      description: 'Bybit API \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e',
      error_code: 'API_UNREACHABLE',
      error_text: e.message,
      duration: Math.round(downDuration / 1000) + ' \u0441\u0435\u043a',
      consequences: '\u0422\u043e\u0440\u0433\u043e\u0432\u043b\u044f \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u0430, \u043e\u0440\u0434\u0435\u0440\u0430 \u043d\u0435 \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0442\u0441\u044f',
      auto_action: '\u0411\u043e\u0442 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d (botStopped=true)',
      manual_action: '\u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 status.bybit.com \u0438 \u043f\u0435\u0440\u0435\u0437\u0430\u043f\u0443\u0441\u0442\u0438\u0442\u0435 \u0431\u043e\u0442\u0430 \u043a\u043e\u0433\u0434\u0430 API \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0441\u044f'
    });
  } else {
    alerts.push({
      level: 'WARNING',
      key: 'api_down',
      description: `Bybit API \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e (${Math.round(downDuration / 1000)} \u0441\u0435\u043a)`,
      cause: e.message,
      recommendation: '\u041e\u0436\u0438\u0434\u0430\u043d\u0438\u0435 \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f. \u0411\u043e\u0442 \u0431\u0443\u0434\u0435\u0442 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d \u0447\u0435\u0440\u0435\u0437 2 \u043c\u0438\u043d.'
    });
  }
}

// =============================================
// b) Balance & Positions (only if API is up)
// =============================================
let totalEquity = 0;
let positions = [];

if (apiOk) {
  // Get wallet balance
  try {
    const balResp = await signedGet.call(this, '/v5/account/wallet-balance', { accountType: 'UNIFIED' });
    if (balResp.retCode === 0) {
      totalEquity = parseFloat(balResp.result.list[0].totalEquity || '0');
      if (totalEquity <= 0) {
        alerts.push({
          level: 'CRITICAL',
          key: 'zero_balance',
          description: `\u0411\u0430\u043b\u0430\u043d\u0441 \u0440\u0430\u0432\u0435\u043d $${totalEquity.toFixed(2)}`,
          error_code: 'ZERO_BALANCE',
          error_text: '\u041d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0441\u0440\u0435\u0434\u0441\u0442\u0432 \u0434\u043b\u044f \u0442\u043e\u0440\u0433\u043e\u0432\u043b\u0438',
          duration: '-',
          consequences: '\u0422\u043e\u0440\u0433\u043e\u0432\u043b\u044f \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u0430',
          auto_action: '\u041c\u043e\u043d\u0438\u0442\u043e\u0440\u0438\u043d\u0433 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442\u0441\u044f',
          manual_action: '\u041f\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435 \u0441\u0447\u0435\u0442 \u0438\u043b\u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u0430\u043a\u043a\u0430\u0443\u043d\u0442'
        });
      }
    }
  } catch(e) {}

  // Get positions
  try {
    const posResp = await signedGet.call(this, '/v5/position/list', { category: 'linear', settleCoin: 'USDT' });
    if (posResp.retCode === 0) {
      positions = (posResp.result?.list || []).filter(p => parseFloat(p.size) > 0);

      // Check positions count
      if (positions.length > MAX_OPEN_POSITIONS) {
        alerts.push({
          level: 'WARNING',
          key: 'too_many_positions',
          description: `\u041e\u0442\u043a\u0440\u044b\u0442\u043e ${positions.length} \u043f\u043e\u0437\u0438\u0446\u0438\u0439 (\u043c\u0430\u043a\u0441: ${MAX_OPEN_POSITIONS})`,
          cause: '\u041f\u0440\u0435\u0432\u044b\u0448\u0435\u043d \u043b\u0438\u043c\u0438\u0442 \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u0445 \u043f\u043e\u0437\u0438\u0446\u0438\u0439',
          recommendation: '\u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u0435 \u043f\u043e\u0437\u0438\u0446\u0438\u0438 \u0438 \u0437\u0430\u043a\u0440\u043e\u0439\u0442\u0435 \u043b\u0438\u0448\u043d\u0438\u0435'
        });
      }

      // Check positions without stop-loss
      for (const pos of positions) {
        const sl = parseFloat(pos.stopLoss || '0');
        if (sl === 0) {
          alerts.push({
            level: 'CRITICAL',
            key: `no_sl_${pos.symbol}`,
            description: `\u041f\u043e\u0437\u0438\u0446\u0438\u044f ${pos.symbol} \u0431\u0435\u0437 \u0441\u0442\u043e\u043f-\u043b\u043e\u0441\u0441\u0430!`,
            error_code: 'NO_STOP_LOSS',
            error_text: `${pos.side} ${pos.size} ${pos.symbol}, \u0432\u0445\u043e\u0434: ${pos.avgPrice}`,
            duration: '-',
            consequences: '\u041d\u0435\u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u043d\u044b\u0439 \u0440\u0438\u0441\u043a \u043f\u043e\u0442\u0435\u0440\u044c',
            auto_action: '\u0417\u0430\u043f\u0438\u0441\u044c \u0432 \u043b\u043e\u0433 (\u0430\u0432\u0442\u043e-SL \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u0435\u043d)',
            manual_action: '\u0423\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0435 \u0441\u0442\u043e\u043f-\u043b\u043e\u0441\u0441 \u0432\u0440\u0443\u0447\u043d\u0443\u044e \u0438\u043b\u0438 \u0447\u0435\u0440\u0435\u0437 Telegram'
          });
        }

        // Check position age > 24h
        const createdTime = parseInt(pos.createdTime || '0');
        if (createdTime > 0 && (now - createdTime) > 24 * 60 * 60 * 1000) {
          const ageHours = Math.round((now - createdTime) / (60 * 60 * 1000));
          alerts.push({
            level: 'WARNING',
            key: `old_pos_${pos.symbol}`,
            description: `\u041f\u043e\u0437\u0438\u0446\u0438\u044f ${pos.symbol} \u043e\u0442\u043a\u0440\u044b\u0442\u0430 ${ageHours} \u0447\u0430\u0441\u043e\u0432`,
            cause: '\u041f\u043e\u0437\u0438\u0446\u0438\u044f \u043d\u0435 \u0437\u0430\u043a\u0440\u044b\u0442\u0430 \u0431\u043e\u043b\u0435\u0435 24 \u0447\u0430\u0441\u043e\u0432',
            recommendation: '\u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u0430\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u043e\u0441\u0442\u044c \u043f\u043e\u0437\u0438\u0446\u0438\u0438 \u0438 \u0440\u0430\u0441\u0441\u043c\u043e\u0442\u0440\u0438\u0442\u0435 \u0437\u0430\u043a\u0440\u044b\u0442\u0438\u0435'
          });
        }
      }
    }
  } catch(e) {}

  // =============================================
  // c) Daily P&L Monitoring
  // =============================================
  try {
    const todayStart = new Date();
    todayStart.setUTCHours(0, 0, 0, 0);
    const startTime = todayStart.getTime().toString();

    const pnlResp = await signedGet.call(this, '/v5/position/closed-pnl', {
      category: 'linear', startTime, limit: '100'
    });
    if (pnlResp.retCode === 0) {
      const dailyPnl = (pnlResp.result?.list || []).reduce((sum, p) => sum + parseFloat(p.closedPnl), 0);

      // Track hourly balance snapshots
      if (!cfg.health_balance_history) cfg.health_balance_history = [];
      cfg.health_balance_history.push({ ts: now, equity: totalEquity });
      // Keep only last 24h of snapshots
      cfg.health_balance_history = cfg.health_balance_history.filter(h => now - h.ts < 24 * 60 * 60 * 1000);

      // Check if balance dropped 5%+ in last hour
      const oneHourAgo = now - 60 * 60 * 1000;
      const hourOldSnapshots = cfg.health_balance_history.filter(h => h.ts <= oneHourAgo);
      if (hourOldSnapshots.length > 0) {
        const oldEquity = hourOldSnapshots[hourOldSnapshots.length - 1].equity;
        if (oldEquity > 0) {
          const dropPercent = ((oldEquity - totalEquity) / oldEquity) * 100;
          if (dropPercent >= 5) {
            alerts.push({
              level: 'CRITICAL',
              key: 'balance_drop_5pct',
              description: `\u0411\u0430\u043b\u0430\u043d\u0441 \u0443\u043f\u0430\u043b \u043d\u0430 ${dropPercent.toFixed(1)}% \u0437\u0430 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0439 \u0447\u0430\u0441`,
              error_code: 'BALANCE_DROP',
              error_text: `$${oldEquity.toFixed(2)} \u2192 $${totalEquity.toFixed(2)} (-${dropPercent.toFixed(1)}%)`,
              duration: '1 \u0447\u0430\u0441',
              consequences: '\u0411\u044b\u0441\u0442\u0440\u0430\u044f \u043f\u043e\u0442\u0435\u0440\u044f \u043a\u0430\u043f\u0438\u0442\u0430\u043b\u0430',
              auto_action: '\u041c\u043e\u043d\u0438\u0442\u043e\u0440\u0438\u043d\u0433 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0430\u0435\u0442\u0441\u044f',
              manual_action: '\u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u0435 \u043f\u043e\u0437\u0438\u0446\u0438\u0438 \u0438 \u0440\u0430\u0441\u0441\u043c\u043e\u0442\u0440\u0438\u0442\u0435 \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0443 \u0431\u043e\u0442\u0430'
            });
          }
        }
      }
    }
  } catch(e) {}
}

// =============================================
// d) Error Tracking
// =============================================
const healthErrors = cfg.health_errors;
const oneHourAgo = now - 60 * 60 * 1000;

// Clean up old errors (older than 1 hour)
for (const wfKey of Object.keys(healthErrors)) {
  if (Array.isArray(healthErrors[wfKey])) {
    healthErrors[wfKey] = healthErrors[wfKey].filter(e => e.ts > oneHourAgo);
    if (healthErrors[wfKey].length === 0) delete healthErrors[wfKey];
  }
}

// Check consecutive errors per workflow
for (const [wfKey, errors] of Object.entries(healthErrors)) {
  if (!Array.isArray(errors)) continue;
  // Count consecutive recent errors (last 3)
  const recent = errors.slice(-3);
  if (recent.length >= 3 && recent.every(e => e.failed)) {
    alerts.push({
      level: 'WARNING',
      key: `consec_errors_${wfKey}`,
      description: `\u0412\u043e\u0440\u043a\u0444\u043b\u043e\u0443 ${wfKey}: 3+ \u043e\u0448\u0438\u0431\u043a\u0438 \u043f\u043e\u0434\u0440\u044f\u0434`,
      cause: `\u041f\u043e\u0441\u043b\u0435\u0434\u043d\u044f\u044f: ${recent[recent.length-1].msg || 'unknown'}`,
      recommendation: '\u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u043b\u043e\u0433\u0438 \u0432\u043e\u0440\u043a\u0444\u043b\u043e\u0443 \u0438 \u043f\u0435\u0440\u0435\u0437\u0430\u043f\u0443\u0441\u0442\u0438\u0442\u0435'
    });
  }
  // Check failure rate > 20% per hour
  const totalInHour = errors.length;
  const failedInHour = errors.filter(e => e.failed).length;
  if (totalInHour >= 5 && (failedInHour / totalInHour) > 0.2) {
    alerts.push({
      level: 'WARNING',
      key: `failure_rate_${wfKey}`,
      description: `\u0412\u043e\u0440\u043a\u0444\u043b\u043e\u0443 ${wfKey}: \u0447\u0430\u0441\u0442\u043e\u0442\u0430 \u043e\u0448\u0438\u0431\u043e\u043a ${Math.round(failedInHour/totalInHour*100)}%`,
      cause: `${failedInHour} \u043e\u0448\u0438\u0431\u043e\u043a \u0438\u0437 ${totalInHour} \u0437\u0430\u043f\u0443\u0441\u043a\u043e\u0432 \u0437\u0430 \u0447\u0430\u0441`,
      recommendation: '\u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u043a\u043e\u043d\u0444\u0438\u0433\u0443\u0440\u0430\u0446\u0438\u044e \u0438 API \u043a\u043b\u044e\u0447\u0438'
    });
  }
}

// =============================================
// e) Alert Deduplication
// =============================================
const DEDUP_INTERVAL = 15 * 60 * 1000; // 15 minutes
const alertsSent = cfg.health_alerts_sent;
const filteredAlerts = [];

for (const alert of alerts) {
  const lastSent = alertsSent[alert.key] || 0;
  if (alert.level === 'INFO' || (now - lastSent) > DEDUP_INTERVAL) {
    filteredAlerts.push(alert);
    alertsSent[alert.key] = now;
  }
}

// =============================================
// f) Store health history & auto-cleanup (7 days)
// =============================================
cfg.health_history.push({
  ts: now,
  apiOk,
  apiResponseTime,
  equity: totalEquity,
  posCount: positions.length,
  alertCount: filteredAlerts.length
});

const sevenDaysAgo = now - 7 * 24 * 60 * 60 * 1000;
cfg.health_history = cfg.health_history.filter(h => h.ts > sevenDaysAgo);

// Clean old alert dedup timestamps
for (const key of Object.keys(alertsSent)) {
  if (now - alertsSent[key] > sevenDaysAgo) {
    delete alertsSent[key];
  }
}

return [{
  json: {
    alerts: filteredAlerts,
    hasAlerts: filteredAlerts.length > 0,
    apiOk,
    apiResponseTime,
    totalEquity,
    positionsCount: positions.length
  }
}];
